\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 In\plain \f1\lang1033\fs24 [c]\plain \f1\i\lang1033\fs24 ipit ammonitio eivsdem per qvam ostenditur qvantvm boni sit lectionem divinam diligere\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 et qvantvm mali sit ab illivs notitia vel inqvisitione desinere\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Propitio Christo\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 fratres karissimi\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 ita lectionem diuinam auido\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 ut in nobis impleatur illud quod scriptum est\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Qui docti fuerint\plain \f1\lang1033\fs24  ... (Dn 12,3). \plain \f1\i\lang1033\fs24 Quod ipse prestare dignetur\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 .  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
