\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Haec sunt (instituta) qu\u281 e iussa sunt (a sanctis patribus) discere}}\plain \f1\lang1033\fs24  (\plain \f1\i\lang1033\fs24 ut\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ecclesiasticos \plain \f1\lang1033\fs24 [mit \u252 \'fcbergeschriebenem \plain \f1\i\lang1033\fs24 i\plain \f1\lang1033\fs24  in \plain \f1\i\lang1033\fs24 ecclesiastici\plain \f1\lang1033\fs24  korr.] (\plain \f1\i\lang1033\fs24 discant\plain \f1\lang1033\fs24 ) ...; eingeklammerte Worte von sp\u228 \'e4terer Hand \u252 \'fcber der Zeile erg\u228 \'e4nzt; am Rand mit Bleistift Verweis auf \plain \f1\scaps\lang1033\fs24 Sanftl\plain \f1\lang1033\fs24  I, p. 513 und 675 ({\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 14508}}\plain \f1\lang1033\fs24 ).
