\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 125\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -127\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , 133\plain \f1\super\lang1033\fs24 v{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17  Guido Aretinus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Regulae rhythmicae}}
