\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 CLA 9, 1297. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , Schreibschulen 1, S. 190f. Nr. 11, S. 174, 184, 216 Anm. 1, S. 220. \endash  \plain \f1\scaps\lang1033\fs20 Bierbrauer\plain \f1\lang1033\fs20 , S. 59 Nr. 106. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff/Ebersperger\plain \f1\lang1033\fs20 , Katalog 2, S. 256 Nr. 3191. \endash  \plain \f1\scaps\lang1033\fs20 Bergmann/Stricker\plain \f1\lang1033\fs20 , Katalog 3, S. 1125f. Nr. 584.}

