\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Moralia in Iob (Pars quarta, liber XVII-XXII)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Incipit Moralium\plain \f1\lang1033\fs24  [Wort auf Rasur stehend; \plain \f1\i\lang1033\fs24 or\plain \f1\lang1033\fs24  von \plain \f1\i\lang1033\fs24 Moraliorum\plain \f1\lang1033\fs24  durch Rasur mangelhaft getilgt] \plain \f1\i\lang1033\fs24 sancti Gregorii in Iob\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 pa\plain \f1\lang1033\fs24 [r]\plain \f1\i\lang1033\fs24 s\plain \f1\lang1033\fs24  [\plain \f1\i\lang1033\fs24 a\plain \f1\lang1033\fs24  aus \plain \f1\i\lang1033\fs24 r\plain \f1\lang1033\fs24  schlecht korr., folgendes \plain \f1\i\lang1033\fs24 a\plain \f1\lang1033\fs24  getilgt] \plain \f1\i\lang1033\fs24 quarta\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 liber\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 XUII\plain \f1\lang1033\fs24 ; (215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Explicit liber XXII pars quarta\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Sequitur XXIII in Helyu uerbis editus\plain \f1\lang1033\fs24 ; (94\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) am unteren Rand Anfang eines Alphabetverses (teilweise getilgt und verwischt, kaum lesbar) [Clam] [K]\plain \f1\i\lang1033\fs24 raton\plain \f1\lang1033\fs24  \u8230 \'85; meist am oberen Rand der Rectoseiten das jeweilige Kapitel aus Iob mit roten arabischen Zahlen (oft mit Griffel vorgeschrieben) zwischen zwei Punkten angegeben (Beginn rot im Text vermerkt und Kapitelzahl am Rand angegeben), 14./15. Jh.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
