\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ps.-Beda Venerabilis}}\plain \f1\b\lang1033\fs24 :) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Homiliae de epistulis Pauli, pars prima (Collectio Gymnici)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Prolog (verst\u252 \'fcmmelt; erstes Bl. der Lage fehlt ganz, bei den beiden folgenden etwa ein Drittel): // \plain \f1\i\lang1033\fs24 h\plain \f1\lang1033\fs24 [umani generis per dei largitatem om]\plain \f1\i\lang1033\fs24 nipot\plain \f1\lang1033\fs24 [ens renouatur] ... \endash  ... \plain \f1\i\lang1033\fs24 ad ae\plain \f2\i\lang1024\fs24 tern\u281 \'ea\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 beatitudinis gaudia eorum praecibus adiuti per dei gratiam peruenire mereatur\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 eius adiutorio et uoluntate\plain \f1\lang1033\fs24  ...; (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -165\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 62 Homiliae: >\plain \f1\i\lang1033\fs24 In nomine domini nostri Iesu Christi\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 In hoc codice con\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 tinentur\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 explanationes\plain \f1\lang1033\fs24  >\plain \f2\i\lang1024\fs24 excarsat\u281 \'ea lectionum seu epis\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 tolarum dominicis diebus seu fes\plain \f1\lang1033\fs24 >\plain \f1\i\lang1033\fs24 tiuitatibus nec non et ferias\plain \f1\lang1033\fs24  / \plain \f1\i\lang1033\fs24 a uigilia de natale domini hora\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 nona usque in ascensa\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 domini\plain \f1\lang1033\fs24 , >\plain \f1\i\lang1033\fs24 idest pars\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 prima\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 In uigilia domini de nona\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 I\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24 Lectio epistulae beati Pauli apostoli ad Romanos\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Fratres\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5650[52].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Paulus seruus Christi Iesu ... (Rm 1,1-6). >Omelia lectionis eiusdem< Gaudeamus, fratres et laetaemur}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 in domino\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 karissimi\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 in sollemnitate presenti quam festiua deuotione\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 praeuenimus\plain \f1\lang1033\fs24  [korr. durch Rasur] ...; (165\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) letzte Homilie (\plain \f1\i\lang1033\fs24 LXU\plain \f1\lang1033\fs24 ) endet wie \plain \f1\i\lang1033\fs24 XLUIIII\plain \f1\lang1033\fs24  (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) mit Leo I. papa, Tractatus LIII c. 3 (CCL 138A, S. 315f., ab Z. 60; fehlt gr\u246 \'f6\u223 \'dftenteils bei Gymnich, p. 144): ... \plain \f1\i\lang1033\fs24 humilitati et patientiae ipsius per omnia congruamur\plain \f1\lang1033\fs24  (!) ... \plain \f1\i\lang1033\fs24 peruenire mereamur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Per dominum nostrum\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 ; im Druck fehlende Homilien (Nr. 44, 49): (110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 XLIIII\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Feria III\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 ebdomada U\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Lectio Danihel prophete\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 In diebus illis\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Congregati sunt Babillonii\plain \f1\lang1033\fs24  ... (Dn 14,27-42). \plain \f1\i\lang1033\fs24 Omelia lectionis eiusdem\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Cum ieiunio Danihel in lacum leonum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ingressus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 est\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 et festina gaudiorum expectat letitia\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Domino auxiliante qui se pro nobis\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 offerebat\plain \f1\lang1033\fs24  ...; (121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 XLUIIII\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Feria III in palmas\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Lectio Hieremiae prophetae\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 In diebus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 illis\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dixit Hieremias: Domine demonstrasti mihi ... (Ier 11,18-20). Omelia lectionis eiusdem. Omnium aeclesiarum iste consensus est }}\plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 ut ad ea\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 quae fidelibus parata sunt praemia peruenire mereamur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Per dominum nostrum\plain \f1\lang1033\fs24  ...; ausgelassene Homilien 28, 29 und 33 (s. r\u246 \'f6mische Z\u228 \'e4hlung) in Clm 14410.           
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Druck/Edition: Homiliae venerabilis Bedae ... in D. Pauli epistolas & alias ueteris et noui testamenti lectiones ... nunc primum excusae. K\u246 \'f6ln: \plain \f1\scaps\lang1033\fs20 Gymnich\plain \f1\lang1033\fs20 , Johann I., 1535 (VD16-Nr. B 1434), Prolog und p. 1-144; s\u228 \'e4mtliche Homilien mit Initium und Drucknachweisen aufgenommen bei \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20  I, p. 182-194 und nochmals IV, p. 149-159 (p. 157 fehlt); Anfangsteil von Homilia \plain \f1\i\lang1033\fs20 XIII\plain \f1\lang1033\fs20  (35\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -36\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; vgl. CPPM 1A, 1959) und >\plain \f1\i\lang1033\fs20 Sabbatum de Susanna\plain \f1\lang1033\fs20 < (89\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -92\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; vgl. CPPM 1B. 3905) bei den Sermones (fragmenta) von Chromatius Aquileiensis CCL 9A, ed. R. \plain \f1\scaps\lang1033\fs20 \u201 \'c9\plain \f1\scaps\lang1033\fs20 taix\plain \f1\lang1033\fs20  / J. \plain \f1\scaps\lang1033\fs20 Lemari\plain \f1\scaps\lang1033\fs20 \u233 \'e9\plain \f1\lang1033\fs20  (1974), S. 155-160 Sermo XXXIV, XX\plain \f3\lang1032\fs20 XV, diese Hs. (Sigle \u947 \'e3\plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 ) ben\u252 \'fctzt; zur bayerischen Untergruppe \plain \f3\lang1032\fs20 \u947 \'e3 der \u8222 \'84famille germanique\ldblquote  vgl. ebd. S. XVI; beide Fragmente bereits zuvor ediert bei J. \plain \f1\scaps\lang1033\fs20 Lemari\plain \f1\scaps\lang1033\fs20 \u233 \'e9\plain \f1\lang1033\fs20 , Un nouveau sermon de Saint Chromace d\rquote Aquil\u233 \'e9e et fragments provenant d\rquote homiliaires bavarois, in: Revue b\u233 \'e9n\u233 \'e9dictine 76 (1966), S. 7-40, hierzu S. 19-26 (diese Hs. Sigle b\plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 ); (92\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 ) Homilie \u8218 \'82De Susanna\lquote  ab \plain \f1\i\lang1033\fs20 Qui ergo liberauit\plain \f1\lang1033\fs20  ... fortgesetzt mit Augustinus, Sermo CCCXLIII c. 3-4; C. \plain \f1\scaps\lang1033\fs20 Lambot\plain \f1\lang1033\fs20 , Le sermon CCCXLIII de S. Augustin \u8222 \'84De Susanna et Ioseph\ldblquote , in: Revue b\u233 \'e9n\u233 \'e9dictine 66 (1956), S. 20-38, hierzu S. 31 Z. 85-99, 101f., 105-107, S. 32 Z. 120-122. \endash  Parallel \u252 \'fcberliefert in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 14410}}\plain \f1\lang1033\fs20 , 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -77\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  (hier weitere Literatur). \endash  CPPM 1B, 3871-3932; Homilien nicht bei \plain \f1\scaps\lang1033\fs20 Gymnich\plain \f1\lang1033\fs20  gedruckt: CPPM 1A, 3321; CPPM 1B, 3916a. \endash  Nennung dieser Hs. bei \plain \f1\scaps\lang1033\fs20 Lambert\plain \f1\lang1033\fs20 , BHM 3B, 700 irrig.     
