\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 201\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -203\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ordo der Glockenweihe}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f2\i\lang1024\fs24 Ordo ad signum \u281 \'eacclesi\u281 \'ea benedicendum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Inprimis dicatur letania postea VI psalmi\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 Miserere mei deus\plain \f1\lang1033\fs24  ...; {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Exorcizo te}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 creatura salis}}\plain \f1\lang1033\fs24\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 per deum uiuum}}\plain \f1\lang1033\fs24  ...; >\plain \f1\i\lang1033\fs24 Benedictio salis\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Uirtutis tue inuictam fortitudinem deprecantes}}\plain \f1\lang1033\fs24  ...; (201\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) >\plain \f2\i\lang1024\fs24 Exorcismus aqu\u281 \'ea\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Discede}}\plain \f1\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 inmunde spiritus ab omnibus}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  / }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 quibus est fides}}\plain \f1\lang1033\fs24  ...; (201\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Alia\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Benedic, domine, hanc aquam}}\plain \f1\lang1033\fs24  ...; >\plain \f1\i\lang1033\fs24 Hic mutatur sal in aquam\plain \f1\lang1033\fs24  ...< \plain \f1\i\lang1033\fs24 Fiat commixtio\plain \f1\lang1033\fs24  ...; (201\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Oratio post commixtionem: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Aeterne omnipotens deus, qui nobis a te conditam creaturam}}\plain \f1\lang1033\fs24  ...; >\plain \f1\i\lang1033\fs24 Post hec cantantur isti psalmi\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 Lauda anima usque in finem\plain \f1\lang1033\fs24 ; (202\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Qui dum canuntur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Lauet pontifex signum de aqua bened\plain \f1\lang1033\fs24 (\plain \f1\i\lang1033\fs24 icta\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 et dicit hanc oracionem\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus qui per beatum Moysen legiferum}}\plain \f1\lang1033\fs24  ...; >\plain \f1\i\lang1033\fs24 Tunc extergat illud cum linteolo mundo et canatur antiphona\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 Uox domini usque in finem cum gloria\plain \f1\lang1033\fs24 ; >\plain \f1\i\lang1033\fs24 Et quot uicibus in psalmis dicit vox domini\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Totidem\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 signa\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 faciat cum crismate de foris in campana et fiunt VII intus autem faciat IIII\plain \f1\i\super\lang1033\fs24 or\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 deinde dicit\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 oracionem\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens sempiterne deus qui ante arcam federis}}\plain \f1\lang1033\fs24  ...; >\plain \f1\i\lang1033\fs24 Tunc ponatur cum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 incensorio ignis et timiama\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 thus et mirra et erigatur signum super incensorium ut totum illud\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 fumum colligat et dicatur antiphona\plain \f1\lang1033\fs24 < (in kleinerer Schrift nachgetragen:) \plain \f1\i\lang1033\fs24 Deus in sancto uia\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 tua\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Psalmus\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Uoce mea cum gloria\plain \f1\lang1033\fs24  (hinzugef\u252 \'fcgt, 13. Jh.: \plain \f1\i\lang1033\fs24 Quo finito dicantur\plain \f1\lang1033\fs24 ); (202\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -203\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens dominator Christe cui secundum assumptionem carnis}}\plain \f1\lang1033\fs24  ...; endet: >\plain \f1\i\lang1033\fs24 T\plain \f2\i\lang1024\fs24 unc sub trina infusione aqu\u281 \'ea sanct\u281 \'ea inpone\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 nomen ei si uelis\plain \f1\lang1033\fs24 <.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u196 \'c4hnlich dem Glockenweihe-Ordo (Rubriken abweichend) bei Walter von \plain \f1\scaps\lang1033\fs20 Arx\plain \f1\lang1033\fs20 , Das Klosterrituale von Biburg (Budapest, Cod. lat. m. ae. Nr. 330, 12. Jh.). Freiburg/Schw. 1970 (Spicilegium Friburgense 14), S. 271-275 Nr. 432, 433, 434 (Text S. 168 Nr. 36), 436-445; \u8218 \'82Fiat commixtio\lquote  vgl. S. 171 Nr. 43; zur Glockenweihe vgl. ebd. S. 134f. (135 Anm. 2 diese Hs. genannt) sowie S. 71f.; zus\u228 \'e4tzliche \u8218 \'82Oratio post commixtionem\lquote  bei \plain \f1\scaps\lang1033\fs20 Franz\plain \f1\lang1033\fs20 , Benediktionen 1, S. 152f. und 182 mit Anm. 4 (hier nach {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 6425}}\plain \f1\lang1033\fs20 , 230\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ). }

