\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 De progeniae\plain \f1\lang1033\fs24  (!)\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Auctor generis mei< mihi pater est,}}\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ego illi filius aut filia\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 ego illi\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 neptis filius aut filia\plain \f1\lang1033\fs24 ; von sp\u228 \'e4terer Hand hinzugef\u252 \'fcgt (ohne erkennbaren Sinn): \plain \f1\i\lang1033\fs24 Conueni\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 conscienciam tuam\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 catagorias \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 praedi\plain \f1\lang1033\fs24 [ca]\plain \f1\i\lang1033\fs24 cio\plain \f1\lang1033\fs24 [.]; \plain \f1\i\lang1033\fs24 Destruisse\plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24 Topan\plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24 Dapsilis largus\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Ut pute usque h\u251 \'fbc\plain \f1\lang1033\fs24 .
