\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 W. A. \plain \f1\scaps\lang1033\fs20 Baehrens\plain \f1\lang1033\fs20 , \u220 \'dcberlieferung und Textgeschichte der lateinisch erhaltenen Origeneshomilien zum Alten Testament. Leipzig 1916 (Texte und Untersuchungen zur Geschichte der altchristlichen Literatur 42/1), S. 168f. \endash  CLA 9, 1299. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , Schreibschulen 1, S. 191f. Nr. 12. \endash  \plain \f1\scaps\lang1033\fs20 Bierbrauer\plain \f1\lang1033\fs20 , S. 59 Nr. 105. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff/Ebersperger\plain \f1\lang1033\fs20 , Katalog 2, S. 258 Nr. 3203.}

