\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 Incipit dicta \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 sancti Basilii episcopi de XIIII \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 remissionibus peccatorum\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 I. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 De milite Christi. II. Itaque est remissio peccatorum}}\plain \f1\i\lang1033\fs24  qua baptizamur in aqua\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 III. Illud quod scriptum est\plain \f1\lang1033\fs24  ... (Io 3,5) ... \plain \f1\i\lang1033\fs24 et latrone cruentato respondente domino\plain \f1\lang1033\fs24  ... (Lc 23,43).
