\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 Incipit predicatio sancti Pauli\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 ad Teclam uirginem.\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Paulus] leuauit uocem suam in medio ecclesiae et}}\plain \f1\i\lang1033\fs24  dixit: Felices mundi conscientia\plain \f1\lang1033\fs24  ..., Reihe von Seligpreisungen (Makarismen).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Admoneo uos sorores meae per dei gratiam qua}}\plain \f1\i\lang1033\fs24  donati sumus ut\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 omne bonum non defuit nec deest aut deesse numquam potest\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Admoneo uos iterum contenete gulam et linguam}}\plain \f1\i\lang1033\fs24  qui contenet gulam\plain \f1\lang1033\fs24  ... \endash  ... \plain \f2\i\lang1024\fs24 cum omnibus qu\u281 \'ea supra diximus regnauimus cum patre\plain \f1\lang1033\fs24  ...; \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (149\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Per tres< uocationes deus uocauit hunc mundum}}\plain \f1\i\lang1033\fs24 : prima est\plain \f1\lang1033\fs24  ... \endash  ... >\plain \f1\i\lang1033\fs24 Tunc res\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 pondit deus illis et dicet\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Quamdiu fecistis uni\plain \f1\lang1033\fs24  ... (Mt 25,40); nahtloser Anschluss \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Primum quidem decet nos audire iustitiam, deinde}}\plain \f1\i\lang1033\fs24  intellegere\plain \f1\lang1033\fs24  ...; \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Primum mandatum est< in lege: Diliges dominum ... (Mt 22,37)}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Nobis ergo omnibus communiter hoc mandatum preceptum est\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 Hieronimus dicit: Qui faciet haec habitauit\plain \f1\lang1033\fs24  (wohl statt habebit) \plain \f1\i\lang1033\fs24 ui\plain \f2\i\lang1024\fs24 tam \u281 \'eaternam. \plain \f1\i\lang1033\fs24 Finit\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 6\plain \f1\lang1033\fs24 (156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Oportet nos< suscitare animas nostras de presentibus}}\plain \f1\i\lang1033\fs24  ad absentia\plain \f1\lang1033\fs24  ...; \plain \f1\super\lang1033\fs24 7\plain \f1\lang1033\fs24 (157\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -158\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus dicit< Mulieribus (!) subdit\u281 e estote uiris ... (Col 3,18-24)}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Elimosinam prolongat dies hominum\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 quicumque perseuerauerit \plain \f1\lang1033\fs24 ... (Mt 10,22 u. \u246 \'f6.).\plain \f1\i\lang1033\fs24  Finit Amen\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 8\plain \f1\lang1033\fs24 (158\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Filioli mei< nolite confidere in regnum huius seculi}}\plain \f1\i\lang1033\fs24  quia ita est\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 ipsi sunt in his locis qui habitant in secula seculorum\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 9\plain \f1\lang1033\fs24 (159\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Terram< qu\u281 \'ea promissa est sanctis pro operibus bonis}}\plain \f2\i\lang1024\fs24  qu\u281 \'ea faciunt \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 et erit deus cum illis et dilebit\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 lacrimas ab eorum \plain \f1\lang1033\fs24 // [oculis?] (bricht ab). 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck: Die lateinischen \u220 \'dcbersetzungen der Acta Pauli et Theclae nebst Fragmenten, Ausz\u252 \'fcgen und Beilagen, hrsg. von Oskar Leopold \plain \f1\scaps\lang1033\fs20 von Gebhardt\plain \f1\lang1033\fs20 . Leipzig 1902 (Texte u. Untersuchungen zur Gesch. d. altchristl. Lit., N. F. VII,2), S. 137 und Nr. 1: S. CIXf. jeweils aus dieser Hs. sowie Andr\u233 \'e9 \plain \f1\scaps\lang1033\fs20 Wilmart\plain \f1\lang1033\fs20 , Extraits d\rquote \plain \f1\i\lang1033\fs20 Acta Pauli\plain \f1\lang1033\fs20 , in: Revue b\u233 \'e9n\u233 \'e9dictine 27 (1910), S. 402-412, bes. 406f. und Nr. 1: S. 408f. nach der damals neuen Hs. Vatikanstadt, BAV, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Reg. lat. 1050}}\plain \f1\lang1033\fs20  (die Varianten von Clm 14446 b im Apparat). \endash  Vgl. \plain \f1\scaps\lang1033\fs20 Siegmund\plain \f1\lang1033\fs20 , S. 39; \plain \f1\scaps\lang1033\fs20 Stegm\plain \f1\scaps\lang1033\fs20 \u252 \'fc\plain \f1\scaps\lang1033\fs20 ller\plain \f1\lang1033\fs20 , RB, 1,229,11 und 21; BHL n. s. 8023a. \endash  Bemerkenswert in dem r\u246 \'f6mischen Zeugen (ein Doppelbl., schon 10. Jh., Vorsatz zu einem Rechtscodex) ist das Nebeneinander der Passio sanctae Theclae und der im Emmeramer Band folgenden ersten Ermahnung als Rest einer vergleichbaren Sammlung, wobei die N\u228 \'e4he zu einer kleinen Gruppe von Predigten irischen Ursprungs auff\u228 \'e4llt: Robert E.\plain \f1\scaps\lang1033\fs20  McNally\plain \f1\scaps\lang1033\fs20  \plain \f1\lang1033\fs20 \u8224 \'86, \u8218 \'82In nomine Dei summi\lquote : Seven Hiberno-Latin sermons, in: Traditio 35 (1979), S. 121-143 mit Wiedergabe der h\u228 \'e4ufiger \u252 \'fcberlieferten Nr. 4 (als I; CPPM 1, 1930) und vor allem von Nr. 6 (Exzerpt aus VI, S. 142,15-26, Doxologie \u228 \'e4hnlich).}

