\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Explanatio fidei sancti Hieronimi ad Augustinum et Alipium episcopos missa\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Credimus in deum patrem omnipotentem cunctorum uisibilium}}\plain \f1\i\lang1033\fs24  et inuisibilium conditorem\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 uel maliuolum uel etiam non catholicum non me hereticum conprobauit\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Druck: PL 45, 1716-1718; PL 48, 488-491. \endash  \plain \f1\scaps\lang1033\fs20 Lambert\plain \f1\lang1033\fs20 , BHM 3A, 316; \plain \f1\scaps\lang1033\fs20 Stegm\plain \f1\scaps\lang1033\fs20 \u252 \'fc\plain \f1\scaps\lang1033\fs20 ller\plain \f1\lang1033\fs20 , RB 4, 6370,7; CPL 731.
