\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \u220 \'dcber dem Schenkungseintrag (s. oben) die Notiz, 15. Jh. \plain \f1\i\lang1033\fs24 Epistole Leonis pape sicut patet\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 vertendo folium\plain \f1\lang1033\fs24 ; dar\u252 \'fcber von anderer Hand \plain \f1\i\lang1033\fs24 Epistole Leonis de\plain \f1\lang1033\fs24  ... (der Rest verblasst bzw. abgeschnitten). 
