\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Extrakt nach Ps.-Johannes Chrysostomus, Homilia \u8218 \'82Iterum de nativitate domini\lquote }}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 Excarpsatum de sermone sancti Iohannis Constantinopolitani episcopi de IIII\plain \f1\i\super\lang1033\fs24 or\plain \f1\i\lang1033\fs24  mensibus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ieiuniorum conputatum secundum solarem numerum\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Inter cetera prophetiae suae miracula Zacharias propheta indicit}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 ut unctio idest crisma nascatur\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Vgl. Opera D. Ioannis Chrysostomi ... [T. II]. Basel 1539, p. 840C lin. 8-D lin. 8 (nach Andr\u233 \'e9 \plain \f1\scaps\lang1033\fs20 Wilmart\plain \f1\lang1033\fs20 , wie oben); parallel \u252 \'fcberliefert in Vatikanstadt, BAV, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Reg. lat. 407}}\plain \f1\lang1033\fs20 , 67\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -68\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  und St. Gallen, StiftsB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. Sang. 446}}\plain \f1\lang1033\fs20 , p. 162-163; vgl. dazu \plain \f1\scaps\lang1033\fs20 Andrieu\plain \f1\lang1033\fs20 , Ordines Romani 1, S. 341. \endash  Zur irrigen Zuweisung der Homilie an Pontius Maximus durch \plain \f1\scaps\lang1033\fs20 Wilmart\plain \f1\lang1033\fs20 , La collection (wie oben), S. 316f. (zu diesem Extrakt Anm. 4) vgl. Wolfgang \plain \f1\scaps\lang1033\fs20 Wenk\plain \f1\lang1033\fs20 , Zur Sammlung der 38 Homilien des Chrysostomus Latinus. Wien 1988 (Wiener Studien, Beih. 10), S. 23 (Nr. 17).   }

