\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Exzerpte aus Hieronymus, Commentarii in Zachariam II, 8}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f2\i\lang1024\fs24 In explanatione Zachari\u281 \'ea prophet\u281 \'ea Hieronimi presbiteri de \plain \f1\i\lang1033\fs24 eisdem ieiuniis ita scriptum est ut\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ait idem propheta\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et factum est uerbum ... (Za 8,18-19). In hoc loco nostrorum multi moda (! lies: multa) dixerunt}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 his qui credunt in eum\plain \f1\lang1033\fs24 . 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Edition: CCL 76A, ed. Marcus \plain \f1\scaps\lang1033\fs20 Adriaen\plain \f1\lang1033\fs20  (1970), S. 819 Z. 501-506, S. 820f. Z. 522f., 526-548, 551-561, 575-592; parallel \u252 \'fcberliefert in Vatikanstadt, BAV, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Reg. lat. 407}}\plain \f1\lang1033\fs20 , 68\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -70\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 .\plain \f1\lang1033\fs24   }

