\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -222\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De septem miraculis (signis) nativitatis Christi}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 De miraculis natiuitatis Christi\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum dominus et saluator noster ad redemptionem humani generis}}\plain \f1\i\lang1033\fs24  in hunc mundum uenire disposuit\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 quaedam signa quae eius figurabant aduentum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 paulo ante demonstrare dignatus est\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 Quod ipse nobis praestare dignetur\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 ut hic bonis operibus eius mereamur gratiam possidere et in futuro ad aeterna gaudia peruenire\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Vgl. dazu \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20  II, p. 801 mit Verweis auf {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 14461}}\plain \f1\lang1033\fs20 , 113\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  \u8218 \'82Signa nativitatis Christi\lquote  (\plain \f1\i\lang1033\fs20 Concordet quoad sensum\plain \f1\lang1033\fs20  \plain \f1\i\lang1033\fs20 cum praecedenti opusculo\plain \f1\lang1033\fs20 ). \plain \f1\lang1033\fs24  }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 222\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ps.-Eusebius Alexandrinus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de Christi passione (Versio latina)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 Incipit omelia de passione domini\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hodie uolumus, fratres dilectissimi, uotum adimplere}}\plain \f1\i\lang1033\fs24  et\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 uerbum dicere de passione domini\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Consilium acceperunt\plain \f1\lang1033\fs24  [erstes \plain \f1\i\lang1033\fs24 e\plain \f1\lang1033\fs24  aus \plain \f1\i\lang1033\fs24 i\plain \f1\lang1033\fs24  korr.] \plain \f2\i\lang1024\fs24 Iud\u281 \'eai contra Iesum\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  quomodo eum perderent\plain \f1\lang1033\fs24  (vgl. Mt 12,14). \plain \f1\i\lang1033\fs24 Congregatis illis in unum uenit Iudas ad eos\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 et dedit eis signum dicens\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 ad quod uenisti\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 amice\plain \f1\lang1033\fs24  (vgl. Mt 26,47\u8210 ?50) \u8230 \'85 \endash  ... \plain \f1\i\lang1033\fs24 et diabolum ligans et mundum liberans omnia in caelo suscepit exsurgens a\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 mortuis\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Cuius est honor\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Lateinische Version eines dem sog. Eusebius Alexandrinus zugeschriebenen griech. Sermo Nr. XVII (vgl. CPG 3 u. Suppl., 5526; Text: PG 62, 721-724 unter den Spuria des Johannes Chrsostomus), der in den bisher bekannten lat. Hss. stets mit Sermo Nr. XV (CPG 3, 5524) zusammengefasst \u252 \'fcberliefert wurde; Druck nach Wien, \u214 \'d6NB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. 1370}}\plain \f1\lang1033\fs20 , 107\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -120\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  (Mondsee, ca. 1.\u8210 ?2. Viertel 9. Jh.; vgl. \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , Schreibschulen 2, S. 24) von Edward K. \plain \f1\scaps\lang1033\fs20 Rand\plain \f1\scaps\lang1033\fs20  \plain \f1\lang1033\fs20 (zuerst in: Modern Philology 2 (1904/05), S. 261-278), erneut herausgegeben mit Erl\u228 \'e4uterungen von Oskar \plain \f1\scaps\lang1033\fs20 Hey\plain \f1\lang1033\fs20 , Eine Predigt \u252 \'fcber Christi H\u246 \'f6llenfahrt, in: Archiv f\u252 \'fcr lateinische Lexikographie und Grammatik 14 (1906), S. 253-268,  Text dieses Sermo (XVII) ab S. 261-265 (fol. 115-120\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  am Rand angegeben); Clm 14540 stellenweise stark abweichend und oft k\u252 \'fcrzer. Zwei weitere Textzeugen der kompilierten Fassung (darunter {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 17181}}\plain \f1\lang1033\fs20 , 112\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -117\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) mitgeteilt von Zbigniew \plain \f1\scaps\lang1033\fs20 Izydorczyk\plain \f1\lang1033\fs20 , Two newly identified manuscripts of the \plain \f1\i\lang1033\fs20 Sermo de confusione diaboli\plain \f1\lang1033\fs20 , in: Scriptorium 43,2 (1989), S. 253-255. \endash  Vgl. \plain \f1\scaps\lang1033\fs20 Siegmund\plain \f1\lang1033\fs20 , S. 73; \plain \f1\scaps\lang1033\fs20 Gryson\plain \f1\lang1033\fs20 , R\u233 \'e9pertoire 1, S. 468 (EUS-A, 1). \u8210 ? Weitere Literatur in LexMA 4 (1989), Sp. 105 (Theofried \plain \f1\scaps\lang1033\fs20 Baumeister\plain \f1\lang1033\fs20 ). }

