\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Transitus Mariae (Anfangsteil)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 In assvmptione s\plain \f2\i\lang1024\fs24 anct\u281 \'ea Marie virginis\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cvm ergo esset Maria uigilans et orans diebus ac noctibus}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 quemadmodum pariter hic omnes adunastis\plain \f1\lang1033\fs24  (!) // (bricht ab, da folgende Lage fehlt; s. oben).   
