\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Erster Abschnitt nach Ps.-Isidorus, Quaestiones de veteri et novo Testamento, qu. XXXVIII,52: >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Septem sunt modi praedicationis< Hoc est docendo}}\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 persuadendo\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 increpando\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 arguendo\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 terrendo\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 multiendo\plain \f1\lang1033\fs24  (! lies mulcendo), \plain \f1\i\lang1033\fs24 promittendo\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 uitam aeternam\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Petite et\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 dabitur\plain \f1\lang1033\fs24  \u8230 \'85 (Mt 7,7; Lc 11,9). \plain \f1\i\lang1033\fs24 Petite patrem\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 querite filium\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 pulsate spiritum sanctum\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 petite\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 orando\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 querite operando\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 pulsate caritatem quia per spiritum sanctum habemus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 caritatem\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Hic apostolus dicit\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Quia caritas dei\plain \f1\lang1033\fs24  \u8230 \'85 (Rm 5,5).     
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
