\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Sanftl \plain \f1\lang1033\fs20 I, p. 571, II, p. 802f\plain \f1\scaps\lang1033\fs20 . \plain \f1\scaps\lang1033\fs20 \endash \plain \f1\scaps\lang1033\fs20  MBK 4/1, S. 125. \plain \f1\scaps\lang1033\fs20 \endash \plain \f1\scaps\lang1033\fs20  \plain \f1\lang1033\fs20 Abdruck des Besitzvermerkes bei Franz \plain \f1\scaps\lang1033\fs20 Fuchs\plain \f1\lang1033\fs20 , Neue Quellen zur Bau- und Kunstgeschichte St. Emmerams im Mittelalter, in: St. Emmeram in Regensburg. Geschichte \endash  Kunst \endash  Denkmalpflege. Kallm\u252 \'fcnz 1992 (Thurn- und Taxis- Studien 18), S. 95-107, hierzu S. 105 Anm. 51.}

