\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ave Maria gracia plena, ave genitrix vite, ave mater saluatoris}}\plain \f1\lang1033\fs24  ... (61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Incipit cursus sancte Marie ante matutinas, dices XII\plain \f1\i\super\lang1033\fs24 es\plain \f1\i\lang1033\fs24  aue Maria et singulis aue adiunge singulos uersus\plain \f1\lang1033\fs24  ...< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In benedictionibus sue dulcedinis preueniat nos gratia matris}}\plain \f1\lang1033\fs24  ... (61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gaude virgo principalis}}\plain \f1\lang1033\fs24 .< ... \endash  ... \plain \f1\i\lang1033\fs24 sic semper regia mater, tecum regina cum domino domina amen\plain \f1\lang1033\fs24  (= AH 30, Nr. 58); (66\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Capitulum\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Fasciculus murre dilectus meus mihi}}\plain \f1\lang1033\fs24  ... (68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Mariengebete: >\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gloriosa virgo Maria ego peccator}}\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Saluto te, sancta Maria regina \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 Sancta Maria dei genitrix mitissima\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Aue Maria gratia plena dei genitrix que es super solem pulcherrima\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 O pia domina dulcissima ornamentum seculi\plain \f1\lang1033\fs24  ... (69\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24 Miserere clementissime domine\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine deus omnipotens qui iustis premia}}\plain \f1\i\lang1033\fs24  et delinquentibus veniam promisisti\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 et bonam perseueranciam usque in finem. Amen\plain \f1\lang1033\fs24 . }

