\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gaius Sallustius Crispus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De coniuratione Catilinae cum glossis et scholiis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Accessus: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Mos erat Romanorum ut unusquisque nobilis apponeret filium suum}}\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 studiis per XV annos\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 de quibus tamen non utimur ulla nisi Catilinaria et Iugurthina\plain \f1\lang1033\fs24 ; fortgesetzt von etwas sp\u228 \'e4terer Hand mit Anonymus Monacensis B, Commentarius in Sallustium (Einleitung bis Cat. 3,1): {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Materia Salustii est Catilina et sui contemporanei facientes ciuile bellum}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 absurdus\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  qui interiori id est intellectu\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Text: \u220 \'dcberschrift \plain \f1\i\lang1033\fs24 Salustius\plain \f1\lang1033\fs24  sp\u228 \'e4tmittelalterlicher Nachtrag (dar\u252 \'fcber u. a. falsche BSB-Signatur mit Bleistift: \plain \f1\i\lang1033\fs24 Cod\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 lat\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 14472\plain \f1\lang1033\fs24 ). {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnis homines qui sese student}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 gaudia agitabantur\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24 Explicit Catilinarivs\plain \f1\lang1033\fs24 <; Interlinearglossen, darunter zwei ahd. Federglossen (12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), eine weitere am Rand (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), \u252 \'fcberwiegend wohl 11. Jh., auf 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  einige in Kursive des 15. Jh.s; Randnotizen in mehreren zeitlichen Schichten (s. oben) mit Glossen, Scholien und Teilen des Kommentars \u8218 \'82Anonymus B Monacensis\lquote , z. B. auf 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zu Cat. 9,2 (Anfang zu \plain \f1\i\lang1033\fs24 Iurgia\plain \f1\lang1033\fs24  fast unleserlich) und 9,4 (= {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 14732}}\plain \f1\lang1033\fs24 , 30\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) oder auf 11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zu Cat. 30,6 (Clm 14732, 34\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ); Scholien (z. T. mit Autorenangabe: Priscian, Servius, Isidor, Augustinus) beginnend auf 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \u252 \'fcber erster Zeile: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Salustius Crispus}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  [re- oder com-?, Stelle auf Rasur unleserlich]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 prehendentes}}\plain \f1\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 se arguit}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 dicens }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8218 \'82}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnis}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 homines}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \lquote }}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Priscianus dicit\plain \f1\lang1033\fs24  ...; }

