\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Principium Iani sanxit tropicus Capricornus}}\plain \f1\lang1033\fs24  / ... \plain \f1\i\lang1033\fs24 Terminat Arcitenens\plain \f1\lang1033\fs24  [nach \plain \f1\i\lang1033\fs24 Arc\plain \f1\lang1033\fs24  L\u252 \'fccke durch Rasur] \plain \f1\i\lang1033\fs24 medio sua signa Decembri\plain \f1\lang1033\fs24 ; Korrekturen und erl\u228 \'e4uternde Glossen von sp\u228 \'e4terer Hand des 12. Jh.s; Trennung vom vorausgehenden Text durch R\u246 \'f6telstrich markiert.
