\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -150\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Hrotsvita Gandeshemensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Opera}}
