\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 [{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 S]icut scribitur a philosopho ethicorum primo quod felicitas est bonum}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 quare hoc uisum est\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 cetera patent\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Explicit reportatum a\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 magistro Th\plain \f1\lang1033\fs24 (oma) \plain \f1\i\lang1033\fs24 super Boecium de consolacione philosophie\plain \f1\lang1033\fs24 ; 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
