\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 [I]\plain \f1\i\lang1033\fs24 ohannes papa Anselmo Lemogin\plain \f3\i\lang1024\fs24 \u281 \'ea\plain \f1\i\lang1033\fs24  ecclesi\plain \f3\i\lang1024\fs24 \u281 \'ea episcopo. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ad limina apostolorum}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f3\i\lang1024\fs24 ut debitum pondus me\u281 \'ea penitenti\u281 \'ea per manum tu\u281 \'ea pietatis alleuietur\plain \f1\lang1033\fs24  (aus \plain \f1\i\lang1033\fs24 alleuiatur\plain \f1\lang1033\fs24  korrigiert).
