\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Prima etas continet in exordio sui creationem mundi}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (vgl. Isidor, Etymologiae V,39,1)\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 hoc est in annum quintum Erardii imperatoris et quartum annum Sysiboti principis gentis gothorum anni {\pict\picscalex100\picscaley100\wmetafile8\picw2150\pich600 } \plain \f1\lang1033\fs24 (vgl. Isidor, Chronica I,417).
