\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Capitulatio: >\plain \f1\i\lang1033\fs24 Incipiunt capitula tractatuum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 subsequentium\plain \f1\lang1033\fs24 < >\plain \f1\i\lang1033\fs24 I\plain \f1\i\super\lang1033\fs24 us\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Tractatus primus in die lucis}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 et mandata eius facimus\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24 Expliciunt capitula tractatuum\plain \f1\lang1033\fs24 .< (6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Incipit primus tractatus eiusdem patris\plain \f1\lang1033\fs24  ... Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Meminit sanctitas vestra ewangelium secundum Iohannem}}\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 ut bene intelligatis loquamur\plain \f1\lang1033\fs24 ; (7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Haupttext: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Quod erat ab initio}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 quam tu credas Christo predicanti\plain \f1\lang1033\fs24 ; ab 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  am rechten oberen Rand rote Ziffern \plain \f1\i\lang1033\fs24 2\plain \f1\lang1033\fs24 -\plain \f1\i\lang1033\fs24 5\plain \f1\lang1033\fs24  (Verweis auf das jeweilige Kapitel des Johannesbriefes).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
