\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 // \plain \f1\i\lang1033\fs24 regiminis orbis\plain \f1\lang1033\fs24  (zu Lucanus, De bello civili VII,54f.: \plain \f1\i\lang1033\fs24 et orbis indulgens regno\plain \f1\lang1033\fs24 ). \plain \f1\i\lang1033\fs24 Ac si dicat, quia diu uult in hac potentia esse\plain \f1\lang1033\fs24  ... (16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Incipit liber VIII: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sonipes aufert magnum a bello}}\plain \f1\lang1033\fs24  ... (31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Incipit VIIII\plain \f1\i\super\lang1033\fs24 us\plain \f2\i\lang1024\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Du\u281 \'ea port\u281 \'ea dicuntur esse in c\u281 \'ealo}}\plain \f1\lang1033\fs24  ... (50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Incipit liber \u183 \'b7X\u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pugnauit fortuna etc. Vnum quasi par erat prosper euentus}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 Dum parat et disponit suos bellatores transferre in u\plain \f1\lang1033\fs24 [acua] (?)\plain \f1\i\lang1033\fs24  u\plain \f1\lang1033\fs24 [ehicula] (?)\plain \f1\i\lang1033\fs24 . subito etc.\plain \f1\lang1033\fs24  (zu Lucanus, De bello civili X,535: \plain \f1\i\lang1033\fs24 dum parat in vacuas Martem transferre carinas\plain \f1\lang1033\fs24 ).
