\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Causa, controuersia, negocium, questio}}\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  contencio\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  disceptacio\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  consultacio\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  comparacio. Causa vocata a casu, quo venit \plain \f1\lang1033\fs24 (vgl. Isidor, Etymologiae, 18, 15, 2-5) ... \endash  ... \plain \f1\i\lang1033\fs24 qualitas est mensura per quam aliquis magnum vel minus ostenditur, ut longus, breuis\plain \f1\lang1033\fs24  (ebd. 2, 26, 7).\plain \f1\i\lang1033\fs24  Qualitas est modus\plain \f1\lang1033\fs24  ...\plain \f1\i\lang1033\fs24  id est quantum sit aut qualitas concors\plain \f1\lang1033\fs24  (?)\plain \f1\i\lang1033\fs24  quantitatis, numerositatis. \plain \f1\lang1033\fs24 Am Rand zus\u228 \'e4tzlich einige Federproben.}

