\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 181\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -203\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Excerpta ex artibus rhetoricis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Ausz\u252 \'fcge aus verschiedenen Rhetoriklehren.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (181\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ad omnem iudicialem causam quemadmodum conueniet inuentionem}}\plain \f1\i\lang1033\fs24 . \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 quod maxime necesse est, exercitatione confirma. Explicit liber III\plain \f1\i\super\lang1033\fs24 us \plain \f1\lang1033\fs24 (\plain \f1\scaps\lang1033\fs24 R\plain \f1\lang1033\fs24 hetorica ad Herennium, 3,1,1-3,24,40); (192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De Memoria. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Epilogos de omni causa rapies}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ...\plain \f1\i\lang1033\fs24  si in animo frequenti usu insculpta permanserint \plain \f1\lang1033\fs24 (Iulius Severianus, Praecepta artis rhetoricae, 24, p. 370, 2-5); (192\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De memoria. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8218 \'82Quid dicam?\lquote  inquit M[arcus] T[ullius]}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ...\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (192\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  in ipsa oratione quasi quendam numerum uersumque conficere\plain \f1\lang1033\fs24  (Julius Victor, Ars rhetorica, p. 95,6 - p.101,12); (193\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 His de causis, cum artis inuentionem Grecorum probassemus}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ...\plain \f1\i\lang1033\fs24  sed in ipsis rebus quandam habet dignitatem. Explicit liber quartus \plain \f1\lang1033\fs24 (\plain \f1\scaps\lang1033\fs24 R\plain \f1\lang1033\fs24 hetorica ad Herennium, 4,8,12-4,13,18); (196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De dispositione. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quot sunt generales modi dispositionis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ...\plain \f1\i\lang1033\fs24  et nichil sit in nobis instabile \plain \f1\lang1033\fs24 (Fortunatianus, Ars rhetorica, 3)\plain \f1\i\lang1033\fs24 ; \plain \f1\lang1033\fs24 (202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -203\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De officio. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Orator}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [is]}}\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 officium est proposita questione ciuili dumtaxat}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  \endash  \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 quam polliticem greci uocant collocantur etc., finis, etc. etc. \plain \f1\lang1033\fs24 (Ps.-Augustinus, De rhetorica, 1, p. 137-138).}

