\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (200\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -217\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Haupttext: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum animaduerterem quamplurimos homines}}\plain \f1\lang1033\fs24  ... (200\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Si deus est animus}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 cum culpa redarguat ipsum \plain \f1\lang1033\fs24 (= Disticha Catonis I, praef. und 1-30), der Text geht direkt zum zweiten Vers des \u8218 \'82Novus Cato\lquote  \u252 \'fcber: (202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -203\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Exaudi}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ,}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  fili}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ,}}\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 mentisque}}\plain \f1\i\lang1033\fs24  repone cubili\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 quem doctrina remordet\plain \f1\lang1033\fs24  (= Novus Cato I, praef. ab Vers 2 und I, 1-30), der Wechsel zwischen den beiden Texten wird folgenderma\u223 \'dfen fortgesetzt: (203\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod iustum est petito}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 concordia nutrit amorem\plain \f1\lang1033\fs24  (= Disticha Catonis I, 31-36); 204\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer; 204\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer bis auf Spruch {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 pastor arator eques}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... (= \plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Proverbia 20818); (205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Seruorum ob culpam}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 meminisse malorum est\plain \f1\lang1033\fs24  (= Disticha Catonis I, 37-40, II, 1-15), (206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Exige rem iustam}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 est homo preteritarum\plain \f1\lang1033\fs24  (= Novus Cato I, 31 - II, 15), (207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Non te colaudas}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 cernit id ipsum \plain \f1\lang1033\fs24 (= Disticha Catonis II, 16-31), (208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -209\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nemo sibi laudem}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 sibi sepe reuelat\plain \f1\lang1033\fs24  (= Novus Cato II, 16-34); (209\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -210\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hoc quicumque cupis}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 est aliena magistra\plain \f1\lang1033\fs24  (= Disticha Catonis III, praef. und 1-13), (210\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quisquis adesse}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 est exemplar habendum\plain \f1\lang1033\fs24  (= Novus Cato III, praef. und 1-14), (211\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod potes}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 vis bonus esse parenti\plain \f1\lang1033\fs24  (= Disticha Catonis III, 14-24), (211\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -212\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[17].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tractet opus}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 vis offendere patrem\plain \f1\lang1033\fs24  (= Novus Cato III, 15-25), (212\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -213\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Securam quecumque [!] cupis deducere vitam}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 fortuna recessit\plain \f1\lang1033\fs24  (= Disticha Catonis IV, praef. und 1-19, fehlt zweiter Vers von Strophe 19), (213\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[19].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vitam securams}}\plain \f1\i\lang1033\fs24  si vis deducere\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 non deserijt vnquam \plain \f1\lang1033\fs24 (= Novus Cato IV, Praef. und 1-19, 1. Strophe), (214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Proposicio cuncta tacito}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 mors corporis umbra\plain \f1\lang1033\fs24  (= Disticha Catonis IV, 20-37), (215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ars manet}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 post vestigia vadit\plain \f1\lang1033\fs24  (= Novus Cato IV, 19, 2. Strophe,-37), (216\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Thure deum placa}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 coniungere binos\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Explicit antiquus Katho\plain \f1\lang1033\fs24  (= Disticha Catonis IV, 38-49), (217\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Victima seruetur}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 coniunxit carmina bina\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Explicit nous Katho\plain \f1\lang1033\fs24 . (= Novus Cato IV, 38-49). Die Verse der Disticha Catonis sind am Rand nummeriert. Beide Texte sind mit Interlinear- und Randglossenkommentar versehen; (199\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) zus\u228 \'e4tzlicher Kommentar (zu Disticha Catonis I, 7-12): {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Constans et lenis. Item constancia prelati dicitur}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 Rumores fuge\plain \f1\lang1033\fs24  (vgl. Disticha Catonis I, 12). \plain \f1\i\lang1033\fs24 Notandum actor dicitur ab agendo\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 nullus stultus tacere potest\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Etc\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\chcbpat7 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Edition: (Disticha Catonis) Disticha Catonis, ed. Marcus \plain \f1\scaps\lang1033\fs20 Boas\plain \f1\lang1033\fs20  / Henricus Johannes \plain \f1\scaps\lang1033\fs20 Botschuyver\plain \f1\lang1033\fs20 . Amsterdam 1952 bzw. Dicta Catonis, in: Minor latin poets, ed. J. Wight \plain \f1\scaps\lang1033\fs20 Duff \plain \f1\lang1033\fs20 / Arnold M. \plain \f1\scaps\lang1033\fs20 Duff\plain \f1\lang1033\fs20 . London 1934 (Loeb Classical Library), S. 592-621; (Novus Cato) Friedrich \plain \f1\scaps\lang1033\fs20 Zarncke\plain \f1\lang1033\fs20 , Beitr\u228 \'e4ge zur mittellateinischen Spruchpoesie, in: Berichte \u252 \'fcber die Verhandlungen der k\u246 \'f6niglich s\u228 \'e4chsischen Gesellschaft der Wissenschaften zu Leipzig. Philologisch-historische Classe 15 (1863) S. 23-78, hierzu S. 31-48 (mit einigen Abweichungen von dieser Hs.). \endash  Zum Novus Cato und zu seiner \u220 \'dcberlieferung vgl. \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia carminum 10340; Franz-Joseph \plain \f1\scaps\lang1033\fs20 Worstbrock\plain \f1\lang1033\fs20 , in: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 6 (1987) Sp. 1239-1240; Nikolaus\plain \f1\scaps\lang1033\fs20  Henkel\plain \f1\lang1033\fs20 , Deutsche \u220 \'dcbersetzungen lateinischer Schultexte. Ihre Verbreitung und Funktion im Mittelalter und in der fr\u252 \'fchen Neuzeit.\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 M\u252 \'fcnchen u. a. 1988 (M\u252 \'fcnchener Texte und Untersuchungen zur deutschen Literatur des Mittelalters 90), S. 274-275.}

