\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Sanftl \plain \f1\lang1033\fs20 I, p. 751-754, 777, 785f., 790. \endash  Oswald \plain \f1\scaps\lang1033\fs20 Holder-Egger\plain \f1\lang1033\fs20 , Handschriften der K\u246 \'f6niglichen Bibliothek zu M\u252 \'fcnchen II, in: NA 9 (1884), S. 543-600, hierzu S. 561. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , St. Emmeram im Sp\u228 \'e4tmittelalter, S. 148 Anm. 195.}

