\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sciendum summarie, quod in electione praepositure Salczburgensis}}\plain \f1\i\lang1033\fs24  hoc ordine procedendum est. Et primo congregetur capitulum\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 auditis cum ibi notatis de electi\plain \f1\lang1033\fs24 [onibus]//; Text bricht mitten im Wort ab, Rest der Seite leer.
