\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Evangelienanf\u228 \'e4nge und Gebete f\u252 \'fcr eine Flur- oder Fronleichnamsprozession}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Initium sancti euangelii secundum Iohannem\plain \f1\lang1033\fs24 .< (1\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) Io 1,1-15; (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Sacerdos dicat versus\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24 Fiat misericordia tua\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens sempiterne deus te supplices deprecamur}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ... (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 obsecrantes misericordiam consequantur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Per Christum dominum nostrum\plain \f1\lang1033\fs24  (I = \plain \f1\scaps\lang1033\fs24 Franz\plain \f1\lang1033\fs24  II, S. 88, Nr. 2; Corpus orationum, 4076); >\plain \f1\i\lang1033\fs24 Initium sancti euangelii secundum Matheum\plain \f1\lang1033\fs24 .< (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Mt 1,1-16; (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Per ista uerba sancti euangelii\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 liberet\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 a fulgure et tempestate atque ab omibus malis et periculis\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24 Sacerdos dicat versus\plain \f1\lang1033\fs24 .< (4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ostende nobis domine\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quesumus, omnipotens deus, ut intercessio sancte dei genitricis Marie}}\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 et dextera tue potentie aeris conteras potestates\plain \f1\lang1033\fs24  (II = \plain \f1\scaps\lang1033\fs24 Franz\plain \f1\lang1033\fs24  II, S. 78, Nr. 3); (4\plain \f1\super\lang1033\fs24 v-r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Initium sancti euangelii secundum Lucam\plain \f1\lang1033\fs24 .< (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lc 1,1-17. (6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Per ista uerba vt supra\plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24 Sacerdos dicat versus\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24 Ostende nobis domine misericordiam tuam\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 .< (6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus qui omnium rerum tibi seruientium naturam}}\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 eius misericordiam sentiamus\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Per Christum dominum nostrum\plain \f1\lang1033\fs24  (III = \plain \f1\scaps\lang1033\fs24 Franz\plain \f1\lang1033\fs24  II, S. 78, Nr. 5; Corpus orationum, 1954); >\plain \f1\i\lang1033\fs24 Initium sancti euangelii secundum Marcum\plain \f1\lang1033\fs24 .< (6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Mc 1,1-8; (7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Per ista uerba vt supra\plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24 Sacerdos dicat versus\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24 Fiat misericordia tua\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Te deprecamur domine, vt dyabolum et omnes angelos eius}}\plain \f1\lang1033\fs24  ... \endash  ... (8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 futuris periculis defendas per Christum\plain \f1\lang1033\fs24  (IV = \plain \f1\scaps\lang1033\fs24 Franz\plain \f1\lang1033\fs24  II, S. 88, Nr. 8); >\plain \f1\i\lang1033\fs24 Alia oratio\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Te domine sancte pater omnipotens eterne deus supplices deprecamur}}\plain \f1\lang1033\fs24 ... \endash  ... (8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 grandines amouere digneris\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Per Christum dominum\plain \f1\lang1033\fs24  (V = \plain \f1\scaps\lang1033\fs24 Franz\plain \f1\lang1033\fs24  II, S. 15, Nr. 5; Corpus orationum 5864).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Auszug aus der Liturgie f\u252 \'fcr eine Prozession, bei der an vier Stationsalt\u228 \'e4ren der Beginn der vier Evangelien gesungen und verschiedene Gebete (F\u252 \'fcrbitten, Wettersegen) gesprochen werden.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Gebete ebenfalls \u252 \'fcberliefert in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 2770}}\plain \f1\lang1033\fs20  (I, IV) aus Aldersbach, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 6425}}\plain \f1\lang1033\fs20  (II, III) aus Freising und {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 22040}}\plain \f1\lang1033\fs20  (V) aus Wessobrunn. \endash  Zum Verh\u228 \'e4ltnis von Wetter- und Fronleichnamsprozession im deutschen Sp\u228 \'e4tmittelalter vgl. Peter \plain \f1\scaps\lang1033\fs20 Browe\plain \f1\lang1033\fs20 , Die Eucharistie im Mittelalter. Liturgiehistorische Forschungen in kulturwissenschaftlicher Absicht, hrsg. von Hubert \plain \f1\scaps\lang1033\fs20 Lutterbach\plain \f1\lang1033\fs20  / Thomas \plain \f1\scaps\lang1033\fs20 Flammer\plain \f1\lang1033\fs20 . M\u252 \'fcnster/Hamburg/London 2003 (Vergessene Theologen 1), S. 295.}
